import { registerEndpoint } from '@projexlight/sdk-webhook';
const { endpoint_id, signing_key_ref } = await registerEndpoint({
  tenant_id, url: 'https://customer.example.com/projex',
  description: 'Pipe lead-created events to our CRM',
});
// signing_key_ref is a vault handle; the actual secret is shown to the customer once via the UI.

import { subscribe } from '@projexlight/sdk-webhook';
await subscribe({
  endpoint_id,
  event_types: ['crm.lead.created.v1', 'billing.invoice.finalized.v1'],
});

// Driven by startDeliveryWorker. Outbound request looks like:
// POST https://customer.example.com/projex
// Content-Type: application/json
// X-Projex-Signature: t=<ts>,v1=<hmac_sha256>
// X-Projex-Event-Type: crm.lead.created.v1
// X-Projex-Delivery-Id: <delivery_uuid>
// <event payload>

// projexcloud-admin /webhooks/dlq page surfaces this; behind the scenes:
await fetch(`/api/webhooks/deliveries/${delivery_id}/replay`, {
  method: 'POST',
  headers: { 'x-admin-ops-token': token },
});

// Triggered from tenant-admin /webhooks/rotate-secret:
// 1. Vault mints a new signing-key version under the same key_id.
// 2. New signature uses v2; old verification key kept for 60s.
// 3. After grace window, old key shredded.
